/**
 * Turns the original photos/artwork in images-src/ into web-sized WebP files in
 * public/img/ (same folder structure and base name, `.webp` extension).
 *
 *   npm run images            # only converts new or changed files
 *   npm run images -- --force # re-encode everything
 *
 * To add a photo: drop the original (any size, jpg/png/heic…) into
 * images-src/<folder>/, run `npm run images`, then reference it in the code as
 * /img/<folder>/<name>.webp.
 *
 * public/img/hero/ is generated by scripts/cut_cow.py and is left alone.
 */
import { readdir, stat, mkdir, copyFile } from 'node:fs/promises';
import { join, relative, dirname, extname, basename, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { cpus } from 'node:os';
import sharp from 'sharp';

const ROOT = resolve(process.argv.find((a) => a.startsWith('--root='))?.slice(7) ?? join(dirname(fileURLToPath(import.meta.url)), '..'));
const SRC = join(ROOT, 'images-src');
const OUT = join(ROOT, 'public', 'img');
const FORCE = process.argv.includes('--force');

/** Photos: longest edge ≤ 2000 px (sharp on retina, full-bleed heroes included). */
const PHOTO = { maxEdge: 2000, webp: { quality: 80, effort: 5, smartSubsample: true } };
/** Folders whose photos only ever show small (e.g. the board's portrait cards). */
const MAX_EDGE_BY_FOLDER = { officers: 1200 };
/** Artwork exported on a big empty canvas: crop to the drawing so CSS sizes the art, not the padding.
 *  Value = longest edge after cropping (these only ever show small). */
const TRIM = { 'art/aggie_open_2026_logo_1': 600, 'art/aggie_open_2026_logo_2': 600 };
/** Artwork with transparency (logos, mascots): crisp edges, keep alpha. */
const ART = { maxEdge: 1600, webp: { quality: 90, alphaQuality: 100, effort: 5 } };
/** Animated GIF/WebP. */
const ANIM = { maxEdge: 900, webp: { quality: 70, effort: 4 } };
/** Social-share preview (og:image) — JPEG for the widest support. */
const OG = { from: 'team_photos/team-2025', to: 'og-image.jpg', w: 1200, h: 630 };

const INPUT = new Set(['.jpg', '.jpeg', '.png', '.gif', '.webp', '.heic', '.heif', '.tif', '.tiff', '.avif']);

async function walk(dir) {
  const out = [];
  for (const e of await readdir(dir, { withFileTypes: true })) {
    if (e.name.startsWith('.')) continue;
    const p = join(dir, e.name);
    if (e.isDirectory()) out.push(...(await walk(p)));
    else if (INPUT.has(extname(e.name).toLowerCase())) out.push(p);
  }
  return out;
}

const mtime = async (p) => (await stat(p).catch(() => null))?.mtimeMs ?? 0;
const kb = (n) => `${(n / 1024).toFixed(0)} KB`;

async function convert(src, dst) {
  const ext = extname(src).toLowerCase();
  const meta = await sharp(src).metadata();
  const animated = (meta.pages ?? 1) > 1;
  const preset = animated ? ANIM : meta.hasAlpha && ext !== '.jpg' && ext !== '.jpeg' ? ART : PHOTO;
  const rel = relative(SRC, src).split(/[\\/]/).join('/');
  const folder = rel.split('/')[0];
  const trim = TRIM[rel.slice(0, -extname(rel).length)];
  const edge = Math.min(preset.maxEdge, MAX_EDGE_BY_FOLDER[folder] ?? Infinity, trim ?? Infinity);
  let img = sharp(src, { animated, limitInputPixels: false }).rotate(); // apply the camera's EXIF orientation, then drop all metadata (incl. GPS)
  if (trim) {
    // trim runs before resize; extend after it, leaving a hair of room so strokes aren't clipped
    img = img.trim({ threshold: 1 }).extend({ top: 6, bottom: 6, left: 6, right: 6, background: { r: 0, g: 0, b: 0, alpha: 0 } });
  }
  img = img.resize({ width: edge, height: edge, fit: 'inside', withoutEnlargement: true });
  await img.webp(preset.webp).toFile(dst);
  // An already-small WebP source can come out bigger after re-encoding: keep the original then.
  if (ext === '.webp' && (await stat(dst)).size > (await stat(src)).size) await copyFile(src, dst);
}

async function main() {
  const files = await walk(SRC);
  // One output per base name; if a folder has both foo.gif and foo.webp, the .webp wins.
  const byOut = new Map();
  for (const f of files) {
    const rel = relative(SRC, f);
    if (rel.startsWith('hero/')) continue;
    const out = join(OUT, dirname(rel), basename(rel, extname(rel)) + '.webp');
    const prev = byOut.get(out);
    if (!prev || extname(f).toLowerCase() === '.webp') byOut.set(out, f);
  }

  let done = 0, skipped = 0, before = 0, after = 0;
  const queue = [...byOut].map(([out, src]) => ({ out, src }));
  const worker = async () => {
    for (let j; (j = queue.shift()); ) {
      if (!FORCE && (await mtime(j.out)) >= (await mtime(j.src))) { skipped++; continue; }
      await mkdir(dirname(j.out), { recursive: true });
      try {
        await convert(j.src, j.out);
      } catch (err) {
        console.error(`✗ ${relative(ROOT, j.src)}: ${err.message}`);
        continue;
      }
      const a = (await stat(j.src)).size, b = (await stat(j.out)).size;
      before += a; after += b; done++;
      console.log(`✓ ${relative(SRC, j.src).padEnd(48)} ${kb(a).padStart(9)} → ${kb(b).padStart(7)}`);
    }
  };
  await Promise.all(Array.from({ length: Math.max(2, Math.min(4, cpus().length)) }, worker));

  // og:image
  const ogSrc = byOut.get(join(OUT, OG.from + '.webp'));
  const ogOut = join(OUT, OG.to);
  if (ogSrc && (FORCE || (await mtime(ogOut)) < (await mtime(ogSrc)))) {
    await sharp(ogSrc).rotate().resize(OG.w, OG.h, { fit: 'cover', position: 'attention' }).jpeg({ quality: 82, mozjpeg: true }).toFile(ogOut);
    console.log(`✓ og:image → ${relative(ROOT, ogOut)}`);
  }

  console.log(`\n${done} converted${done ? ` (${(before / 2 ** 20).toFixed(1)} MB → ${(after / 2 ** 20).toFixed(1)} MB)` : ''}, ${skipped} already up to date.`);
}

main().catch((e) => { console.error(e); process.exit(1); });
